begin;

-- RAPATRIEMENT DES OPPORTUNITES SALESFORCE OUBLIEES A LA REPRISE.
--
-- 320 opportunites Salesforce n'avaient aucune recommandation dans Kimatch. Ce n'est pas une
-- coupure de date propre : 130 opportunites closes en 2024 avaient bien ete reprises, 229 non.
--
-- 104 sont rapatriees ici. Les autres sont ecartees pour une raison precise, jamais par commodite :
--
--   - 214 n'ont AUCUN COMPTE DANS SALESFORCE LUI-MEME (AccountId vide), ni point de
--     livraison, ni contact, ni contrat. Ce sont des coquilles de 2024, toutes « Closed Won »,
--     ne portant qu'une commission et un type d'energie — 526 871 EUR cumules. Kimatch exige un
--     compte sur une recommandation, et rien ne permet de dire lequel. Elles attendent une decision.
--
--   - 2 portent un compte introuvable ou ambigu dans Kimatch, ou un compte de test.
--
-- LE MAPPING N'EST PAS DEVINE. Il a ete releve sur les 1 598 opportunites deja reprises, et
-- chaque correspondance verifiee avant d'etre appliquee :
--   montant, duree, volume, marge/MWh, commissions, budgets, differences   1 598 / 1 598
--   Closed Won  -> CLOTUREE, finalite ACCEPTEE                               825 /   825
--   Abandonee   -> CLOTUREE, finalite EXPIREE                                347 /   347
--   Closed Lost -> CLOTUREE, finalite REFUSEE                                299 /   299
--   marge brute = commission nette + remuneration apporteur                1 469 / 1 471
--   marge nette = commission nette ; marge apporteur = remuneration apporteur
--
-- La priorite est posee a 2, valeur portee par 1 589 des 1 598 lignes deja reprises — et non a
-- 50, la valeur par defaut de la colonne, qui ferait ressortir ces dossiers d'archive au milieu
-- des dossiers vivants. La clause finale refuse d'ecrire par-dessus une
-- recommandation qui porterait deja le meme identifiant Salesforce : la migration peut se
-- rejouer sans rien dupliquer.

insert into recommandations (
  id_salesforce, nom, compte_id, etape_id, finalite_cloture, date_cloture, date_ouverture,
  type_energie_id, fournisseur_compte_id, contact_principal_id,
  type_opportunite, description, commentaire_interne,
  montant, duree_mois, volume_contractuel, marge_nette_mwh,
  commission_interne, commission_nette, remuneration_apporteur,
  budget_ancienne_offre, budget_nouvelle_offre,
  difference_budgetaire, difference_budgetaire_pourcentage,
  marge_brute, marge_nette, marge_apporteur, marge_nette_coeff, priorite
)
